// Generates platform files from design/tokens/tokens.json with Style Dictionary (ADR-022):
//   app/Selah.UI/Styles/Tokens.g.axaml   colour brushes in Light and Dark (Booth) theme dictionaries
//   app/Selah.UI/Styles/Tokens.g.cs      base sizes at 100% text size (scaled at run time, ADR-009)
//   web/tokens/tokens.css                CSS custom properties for the web apps
// Run: pnpm tokens   (the gate checks the generated files are current)
import StyleDictionary from "style-dictionary";

const header = "Generated from design/tokens/tokens.json by design/tokens/build.mjs. Do not edit.";
const pascal = (parts) =>
  parts
    .map((part) => part.split("-").map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(""))
    .join(".");
const px = (value) => Number(String(value).replace("px", ""));
const isMode = (token, mode) => token.path[0] === "color" && token.path[1] === mode;

StyleDictionary.registerFormat({
  name: "selah/avalonia-colors",
  format: ({ dictionary }) => {
    const brushes = (mode) =>
      dictionary.allTokens
        .filter((t) => isMode(t, mode) || (t.path[0] === "color" && t.path[1] === "section"))
        .map((t) => {
          const name = t.path[1] === "section" ? pascal(["section", ...t.path.slice(2)]) : pascal(t.path.slice(2));
          return `        <SolidColorBrush x:Key="Brush.${name}" Color="${t.$value}" />`;
        })
        .join("\n");
    // Elevation (DESIGN-SYSTEM §3). BoxShadows is its own type, so it needs its own element
    // rather than a SolidColorBrush; Booth resolves to "none".
    const shadows = (mode) =>
      dictionary.allTokens
        .filter((t) => t.path[0] === "shadow" && t.path[1] === mode)
        .map((t) => `        <BoxShadows x:Key="Shadow.${pascal(t.path.slice(2))}">${t.$value}</BoxShadows>`)
        .join("\n");
    return `<!-- ${header} -->
<ResourceDictionary xmlns="https://github.com/avaloniaui"
                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <ResourceDictionary.ThemeDictionaries>
    <ResourceDictionary x:Key="Light">
${brushes("light")}
${shadows("light")}
    </ResourceDictionary>
    <ResourceDictionary x:Key="Dark">
${brushes("booth")}
${shadows("booth")}
    </ResourceDictionary>
  </ResourceDictionary.ThemeDictionaries>
</ResourceDictionary>
`;
  },
});

StyleDictionary.registerFormat({
  name: "selah/csharp-sizes",
  format: ({ dictionary }) => {
    const lines = [];
    for (const t of dictionary.allTokens) {
      if (t.$type === "typography") {
        const name = pascal(t.path.slice(1));
        const v = t.$value;
        const family = String(v.fontFamily).includes("Manrope") ? "Display" : "Ui";
        lines.push(`    public static readonly TypeToken ${name.replace(/\./g, "")} = new("${t.path.slice(1).join("-")}", ${px(v.fontSize)}, ${v.fontWeight}, ${v.lineHeight}, ${px(v.letterSpacing ?? 0)}, FontRole.${family});`);
      } else if (t.$type === "dimension") {
        lines.push(`    public const double ${pascal(t.path).replace(/\./g, "")} = ${px(t.$value)};`);
      }
    }
    const steps = dictionary.allTokens.find((t) => t.path.join(".") === "text-scale.steps").$value;
    return `// <auto-generated>${header}</auto-generated>
namespace Selah.UI.Styles;

public enum FontRole
{
    Ui,
    Display,
}

/// <summary>A type-scale entry at 100% text size.</summary>
public sealed record TypeToken(string Name, double Size, int Weight, double LineHeight, double LetterSpacing, FontRole Role);

public static class Tokens
{
    public static readonly int[] TextScaleSteps = [${steps.join(", ")}];

${lines.join("\n")}

    public static readonly TypeToken[] TypeScale = [${dictionary.allTokens
      .filter((t) => t.$type === "typography")
      .map((t) => pascal(t.path.slice(1)).replace(/\./g, ""))
      .join(", ")}];
}
`;
  },
});

StyleDictionary.registerFormat({
  name: "selah/css",
  format: ({ dictionary }) => {
    const vars = (filter) =>
      dictionary.allTokens
        .filter(filter)
        .map((t) => `  --${t.path.slice(t.path[0] === "color" && t.path[1] !== "section" ? 2 : 0).join("-")}: ${Array.isArray(t.$value) ? t.$value.map((f) => (f.includes(" ") ? `"${f}"` : f)).join(", ") : t.$value};`)
        .join("\n");
    const sizes = dictionary.allTokens.filter((t) => t.$type === "dimension" || t.$type === "fontFamily");
    return `/* ${header} */
:root {
${vars((t) => isMode(t, "light") || (t.path[0] === "color" && t.path[1] === "section"))}
${sizes.map((t) => `  --${t.path.join("-")}: ${Array.isArray(t.$value) ? t.$value.map((f) => (f.includes(" ") ? `"${f}"` : f)).join(", ") : t.$value};`).join("\n")}
}
.booth {
${vars((t) => isMode(t, "booth"))}
}
`;
  },
});

const sd = new StyleDictionary({
  source: ["design/tokens/tokens.json"],
  usesDtcg: true,
  log: { verbosity: "silent", warnings: "disabled" },
  platforms: {
    avalonia: {
      buildPath: "app/Selah.UI/Styles/",
      files: [
        { destination: "Tokens.g.axaml", format: "selah/avalonia-colors", filter: (t) => t.$type === "color" || t.$type === "shadow" },
        { destination: "Tokens.g.cs", format: "selah/csharp-sizes" },
      ],
    },
    css: {
      buildPath: "web/tokens/",
      files: [{ destination: "tokens.css", format: "selah/css" }],
    },
  },
});
await sd.buildAllPlatforms();
